local TavernGameMaker = {}
local PRODUCTS = {
    simple_wood_tavern_game = { name = "Preprosta krčemska igra", woodCost = 2, paintCost = 1, time = 3, cost = 50, happiness = 3, prestige = 1, description = "Preprosta krčemska igra za zabavo." },
    carved_dice_game = { name = "Izrezljana kockarska igra", woodCost = 2, leatherCost = 1, paintCost = 1, time = 6, cost = 140, happiness = 4, prestige = 3, description = "Izrezljana kockarska igra za trgovce." },
    silver_trimmed_game = { name = "Srebrnoobrobljena igra", woodCost = 2, silverCost = 1, leatherCost = 1, paintCost = 1, time = 9, cost = 340, happiness = 5, prestige = 7, description = "Srebrnoobrobljena igra za plemiče." },
    gold_inlaid_game = { name = "Zlatovložena igra", woodCost = 2, goldCost = 1, silverCost = 1, leatherCost = 1, paintCost = 1, time = 13, cost = 800, happiness = 6, prestige = 14, description = "Zlatovložena igra za visoke plemiče." },
    jewel_set_game = { name = "Draguljasta igra", woodCost = 2, goldCost = 1, silverCost = 1, leatherCost = 1, paintCost = 1, jewelCost = 1, time = 17, cost = 1800, happiness = 8, prestige = 26, description = "Igra z draguljem za visoko plemstvo." },
    royal_grand_game = { name = "Kraljevski veliki igra", woodCost = 4, goldCost = 2, silverCost = 2, leatherCost = 1, paintCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 4000, happiness = 13, prestige = 58, description = "Velika kraljevska igra z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    tavern_game_workshop = { name = "Krčemska igrarska delavnica", cost = { gold = 220, wood = 140, stone = 100, paint = 6 }, upkeep = 5, qualityBonus = 5 },
    gaming_loft = { name = "Igralna podstrešje", cost = { gold = 880, wood = 280, stone = 220, silver = 6, leather = 6 }, upkeep = 20, qualityBonus = 18 },
    master_game_atelier = { name = "Mojstrski igrarski atelje", cost = { gold = 2500, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_gaming_palace = { name = "Kraljevska igralska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
TavernGameMaker.woodStock = 16; TavernGameMaker.leatherStock = 10; TavernGameMaker.paintStock = 12; TavernGameMaker.silverStock = 6; TavernGameMaker.goldStock = 6; TavernGameMaker.jewelStock = 4; TavernGameMaker.pearlStock = 4
TavernGameMaker.productStock = {}; TavernGameMaker.buildings = {}; TavernGameMaker.maker = nil; TavernGameMaker.activeMaking = {}; TavernGameMaker.totalProducts = 0; TavernGameMaker.dayTimer = 0
function TavernGameMaker.init() TavernGameMaker.woodStock=16; TavernGameMaker.leatherStock=10; TavernGameMaker.paintStock=12; TavernGameMaker.silverStock=6; TavernGameMaker.goldStock=6; TavernGameMaker.jewelStock=4; TavernGameMaker.pearlStock=4; TavernGameMaker.productStock={}; TavernGameMaker.buildings={}; TavernGameMaker.maker=nil; TavernGameMaker.activeMaking={}; TavernGameMaker.totalProducts=0; TavernGameMaker.dayTimer=0; print("[TavernGameMaker] Royal Tavern Game Maker System initialized (6 products, 4 buildings)") end
function TavernGameMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; TavernGameMaker.maker={name=n or ("Igrar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Igrar najet: %s (spretnost: %d)",TavernGameMaker.maker.name,s),"success") end; return true end
function TavernGameMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function TavernGameMaker.build(id) local ok,e=TavernGameMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(TavernGameMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function TavernGameMaker.getQualityBonus() local b=0; for _,bd in ipairs(TavernGameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function TavernGameMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and TavernGameMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and TavernGameMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.paintCost and TavernGameMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and TavernGameMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and TavernGameMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and TavernGameMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and TavernGameMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #TavernGameMaker.buildings==0 then return false,"Potrebna krčemska igrarska delavnica" end; if not TavernGameMaker.maker then return false,"Potreben igrar" end; return true end
function TavernGameMaker.make(pt,qty) qty=qty or 1; local ok,e=TavernGameMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then TavernGameMaker.woodStock=TavernGameMaker.woodStock-d.woodCost*qty end; if d.leatherCost then TavernGameMaker.leatherStock=TavernGameMaker.leatherStock-d.leatherCost*qty end; if d.paintCost then TavernGameMaker.paintStock=TavernGameMaker.paintStock-d.paintCost*qty end; if d.silverCost then TavernGameMaker.silverStock=TavernGameMaker.silverStock-d.silverCost*qty end; if d.goldCost then TavernGameMaker.goldStock=TavernGameMaker.goldStock-d.goldCost*qty end; if d.jewelCost then TavernGameMaker.jewelStock=TavernGameMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then TavernGameMaker.pearlStock=TavernGameMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if TavernGameMaker.maker then t=math.max(1,t-math.floor(TavernGameMaker.maker.skill/13)) end; table.insert(TavernGameMaker.activeMaking,{id="taverngame_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function TavernGameMaker.completeMaking(m) local q=1.0+(TavernGameMaker.getQualityBonus()/100); if TavernGameMaker.maker then q=q+(TavernGameMaker.maker.skill/140) end; q=math.min(2.5,q); TavernGameMaker.productStock[m.productType]=(TavernGameMaker.productStock[m.productType] or 0)+m.quantity; TavernGameMaker.totalProducts=TavernGameMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if TavernGameMaker.maker then TavernGameMaker.maker.itemsMade=TavernGameMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then TavernGameMaker.maker.skill=math.min(100,TavernGameMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Igra izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"taverngame.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function TavernGameMaker.update(dt) if not _G.state then return end; TavernGameMaker.dayTimer=TavernGameMaker.dayTimer+dt; if TavernGameMaker.dayTimer>=30 then TavernGameMaker.dayTimer=0; for i=#TavernGameMaker.activeMaking,1,-1 do local m=TavernGameMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then TavernGameMaker.completeMaking(m); table.remove(TavernGameMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(TavernGameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if TavernGameMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function TavernGameMaker.getStats() return {woodStock=TavernGameMaker.woodStock,leatherStock=TavernGameMaker.leatherStock,paintStock=TavernGameMaker.paintStock,silverStock=TavernGameMaker.silverStock,goldStock=TavernGameMaker.goldStock,jewelStock=TavernGameMaker.jewelStock,pearlStock=TavernGameMaker.pearlStock,productStock=TavernGameMaker.productStock,numBuildings=#TavernGameMaker.buildings,hasMaker=TavernGameMaker.maker~=nil,makerName=TavernGameMaker.maker and TavernGameMaker.maker.name or "—",makerSkill=TavernGameMaker.maker and TavernGameMaker.maker.skill or 0,activeMaking=#TavernGameMaker.activeMaking,totalProducts=TavernGameMaker.totalProducts} end
return TavernGameMaker
